package com.makers.loans;
import com.makers.loans.dto.*; import com.makers.loans.entity.*; import com.makers.loans.repository.*; import com.makers.loans.service.LoanService; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class LoanServiceTest { @Mock LoanRepository loans; @Mock UserRepository users; @InjectMocks LoanService service; @BeforeEach void setup(){MockitoAnnotations.openMocks(this);}
 @Test void debeCrearPrestamoPendiente(){User u=new User("usuario@test.com","x",Role.USER); Loan saved=new Loan(u,new BigDecimal("1000000"),12); when(users.findByEmail("usuario@test.com")).thenReturn(Optional.of(u)); when(loans.save(any(Loan.class))).thenReturn(saved); LoanResponse r=service.create("usuario@test.com",new LoanRequest(new BigDecimal("1000000"),12)); assertEquals(LoanStatus.PENDING,r.status()); assertEquals(new BigDecimal("1000000"),r.amount()); verify(loans).save(any(Loan.class));}
 @Test void debeRechazarCambioSiYaNoEstaPendiente(){User u=new User("admin@test.com","x",Role.ADMIN); Loan l=new Loan(u,new BigDecimal("1000000"),12);l.setStatus(LoanStatus.APPROVED);when(loans.findById(1L)).thenReturn(Optional.of(l));assertThrows(IllegalStateException.class,()->service.changeStatus(1L,LoanStatus.REJECTED));verify(loans,never()).save(any());}}
